SELECT p.*, (SELECT COUNT(*) FROM hr_employee e WHERE e.position_id = p.id AND e.status <> 'LEFT') AS employee_count
FROM hr_position p


        (p.code LIKE CONCAT('%', #{keyword}, '%') OR p.name LIKE CONCAT('%', #{keyword}, '%'))

    AND p.category = #{category}
    AND p.status = #{status}

ORDER BY p.sort, p.id
